import { v2 as cloudinary, type UploadApiResponse } from "cloudinary";
import { NextRequest, NextResponse } from "next/server";
import mongoose from "mongoose";

import {Project, ProjectDoc} from "@/database/projects.model";
import {Service, ServicesModel} from "@/database/services.model";
import connectToDatabase from "@/lib/mongodb";

interface EventsResponse {
  services: ServicesModel[];
  projects: ProjectDoc[];
}

type EventType = "project" | "service";
type ProjectCategory = "Frontend" | "Full Stack" | "Backend";

interface EventFormFields {
  type: EventType;
  title: string;
  description: string;
  slug?: string;
  image?: File;
  tech?: string[];
  category?: string;
  github?: string;
  demo?: string;
  featured?: boolean;
  icon?: string;
  items?: string[];
  accent?: string;
  iconBg?: string;
}

function getRequiredText(formData: FormData, field: string): string {
  const value = formData.get(field);
  return typeof value === "string" ? value.trim() : "";
}

function isProjectCategory(value: string): value is ProjectCategory {
  return value === "Frontend" || value === "Full Stack" || value === "Backend";
}

function isDuplicateKeyError(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    error.code === 11000
  );
}

function parseJsonArray(formData: FormData, field: string): string[] | undefined {
  const value = formData.get(field);

  if (value === null || value === "") {
    return undefined;
  }

  if (typeof value !== "string") {
    throw new Error(`${field} must be a JSON array.`);
  }

  const parsed: unknown = JSON.parse(value);

  if (
    !Array.isArray(parsed) ||
    !parsed.every((item): item is string => typeof item === "string" && item.trim() !== "")
  ) {
    throw new Error(`${field} must be a non-empty array of strings.`);
  }

  return parsed.map((item) => item.trim());
}

function configureCloudinary(): void {
  const cloudName = process.env.CLOUDINARY_CLOUD_NAME;
  const apiKey = process.env.CLOUDINARY_API_KEY;
  const apiSecret = process.env.CLOUDINARY_API_SECRET;

  if (!cloudName || !apiKey || !apiSecret) {
    throw new Error("Cloudinary environment variables are not configured.");
  }

  cloudinary.config({ cloud_name: cloudName, api_key: apiKey, api_secret: apiSecret });
}

async function uploadImage(file: File): Promise<string> {
  if (!file.type.startsWith("image/") || file.size === 0) {
    throw new Error("image must be a non-empty image file.");
  }

  configureCloudinary();
  const buffer = Buffer.from(await file.arrayBuffer());

  const result = await new Promise<UploadApiResponse>((resolve, reject) => {
    const stream = cloudinary.uploader.upload_stream(
      { resource_type: "image", folder: "DevEvent" },
      (error, uploadResult) => {
        if (error || !uploadResult) {
          reject(error ?? new Error("Image upload failed."));
          return;
        }
        resolve(uploadResult);
      },
    );

    stream.end(buffer);
  });

  return result.secure_url;
}

export async function GET(): Promise<NextResponse> {
  try {
    await connectToDatabase();

    const [services, projects] = await Promise.all([
      Service.find().select("-_id -__v").lean<ServicesModel[]>().exec(),
      Project.find().select("-_id -__v").lean<ProjectDoc[]>().exec(),
    ]);

    const events: EventsResponse = { services, projects };

    return NextResponse.json(
      { message: "Events fetched successfully.", events },
      { status: 200 },
    );
  } catch (error: unknown) {
    const errorMessage =
      error instanceof Error
        ? error.message
        : "An unexpected server error occurred.";

    console.error("GET /api/events error:", error);

    return NextResponse.json(
      { message: "Event fetching failed.", error: errorMessage },
      { status: 500 },
    );
  }
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    await connectToDatabase();
    const formData = await request.formData();
    const typeValue = getRequiredText(formData, "type");

    if (typeValue !== "project" && typeValue !== "service") {
      return NextResponse.json(
        { message: 'The "type" field must be either "project" or "service".' },
        { status: 400 },
      );
    }

    const fields: EventFormFields = {
      type: typeValue,
      title: getRequiredText(formData, "title"),
      description: getRequiredText(formData, "description"),
      slug: getRequiredText(formData, "slug") || undefined,
      tech: parseJsonArray(formData, "tech"),
      category: getRequiredText(formData, "category") || undefined,
      github: getRequiredText(formData, "github") || undefined,
      demo: getRequiredText(formData, "demo") || undefined,
      icon: getRequiredText(formData, "icon") || undefined,
      items: parseJsonArray(formData, "items"),
      accent: getRequiredText(formData, "accent") || undefined,
      iconBg: getRequiredText(formData, "iconBg") || undefined,
    };

    if (!fields.title || !fields.description) {
      return NextResponse.json(
        { message: "title and description are required." },
        { status: 400 },
      );
    }

    if (typeValue === "project") {
      const image = formData.get("image");

      if (!(image instanceof File)) {
        return NextResponse.json(
          { message: "image is required for projects." },
          { status: 400 },
        );
      }

      fields.image = image;
      fields.featured = getRequiredText(formData, "featured").toLowerCase() === "true";

      if (
        !fields.tech ||
        !fields.category ||
        !isProjectCategory(fields.category) ||
        !fields.github ||
        !fields.demo
      ) {
        return NextResponse.json(
          {
            message:
              "Projects require tech, a valid category, github, and demo.",
          },
          { status: 400 },
        );
      }

      const imageUrl = await uploadImage(image);
      const project = await Project.create({
        title: fields.title,
        description: fields.description,
        slug: fields.slug,
        image: imageUrl,
        tech: fields.tech,
        category: fields.category,
        github: fields.github,
        demo: fields.demo,
        featured: fields.featured,
      });

      return NextResponse.json(
        { message: "Project created successfully.", event: project },
        { status: 201 },
      );
    }

    if (!fields.icon || !fields.items || !fields.accent || !fields.iconBg) {
      return NextResponse.json(
        { message: "Services require icon, items, accent, and iconBg." },
        { status: 400 },
      );
    }

    const service = await Service.create({
      title: fields.title,
      description: fields.description,
      slug: fields.slug,
      icon: fields.icon,
      items: fields.items,
      accent: fields.accent,
      iconBg: fields.iconBg,
    });

    return NextResponse.json(
      { message: "Service created successfully.", event: service },
      { status: 201 },
    );
  } catch (error: unknown) {
    console.error("POST /api/events error:", error);

    if (error instanceof SyntaxError || error instanceof mongoose.Error.ValidationError) {
      return NextResponse.json(
        { message: error.message },
        { status: 400 },
      );
    }

    if (isDuplicateKeyError(error)) {
      return NextResponse.json(
        { message: "An event with this slug already exists." },
        { status: 409 },
      );
    }

    return NextResponse.json(
      {
        message: "Event creation failed.",
        error: error instanceof Error ? error.message : "Unexpected server error.",
      },
      { status: 500 },
    );
  }
}